import type { Database as SqliteDatabase } from 'better-sqlite3';
import type { Migration } from './types';
import {
  capturedOutboxColumns,
  installMergingOutboxTriggers,
} from '../outbox/mergingOutboxTriggers';

/**
 * A second local edit to a record that was still waiting to sync was queued as
 * its own update whose `base` was the desktop-clock value the first edit wrote,
 * so the server always refused it as a conflict
 * (docs/superpowers/specs/2026-11-05-sync-queue-consecutive-edits-design.md,
 * sections 1 and 5.4). Every outbox table's triggers are regenerated by
 * installMergingOutboxTriggers so the edit folds into the unsent queued update
 * instead, keeping its server-issued `base`.
 *
 * Each table keeps exactly the columns its current insert trigger captures,
 * read from sqlite_master — never the live columns, which would start pushing
 * students.createdAt (031), students.nationalId, students.photoUrl,
 * guardians.photoUrl and grades.enteredAtClose. Only tables that still have an
 * outbox insert trigger are touched, so tables whose triggers an earlier
 * migration dropped (019, 025) stay trigger-free. The freeze/guard BEFORE
 * triggers (040, 043, 044) are left alone. Existing queue rows are untouched.
 */
export const mergeOutboxEdits: Migration = {
  version: 46,
  name: 'merge-outbox-edits',
  up(db: SqliteDatabase): void {
    const tables = (db
      .prepare(`SELECT tbl_name AS t, name FROM sqlite_master WHERE type = 'trigger' ORDER BY tbl_name`)
      .all() as { t: string; name: string }[])
      .filter((row) => row.name === `outbox_${row.t}_insert`)
      .map((row) => row.t);

    for (const table of tables) {
      const columns = capturedOutboxColumns(db, table);
      db.exec(`
        DROP TRIGGER IF EXISTS outbox_${table}_insert;
        DROP TRIGGER IF EXISTS outbox_${table}_update;
        DROP TRIGGER IF EXISTS outbox_${table}_delete;
      `);
      installMergingOutboxTriggers(db, table, columns);
    }
  },
};
